package com.noprobit.vmmanager.webapp.storage;
import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/storage") @CrossOrigin(origins="http://localhost:4200")
public class StorageManagementController {private final StorageManagementService service;public StorageManagementController(StorageManagementService service){this.service=service;}@PostMapping("/open") public StorageManagementService.View open(){return service.view();}@PostMapping("/pools/{action}") public StorageManagementService.View pool(@PathVariable String action,@RequestBody PoolRequest request){return service.pool(action,request.id(),request.name(),request.type(),request.target());}@PostMapping("/volumes/create") public StorageManagementService.View volume(@RequestBody VolumeRequest request){return service.volume(request.name(),request.pool(),request.format(),request.sizeGb());}public record PoolRequest(long id,String name,String type,String target){}public record VolumeRequest(String name,String pool,String format,int sizeGb){}}